SELECT COUNT(*)
FROM check_in
WHERE user_id = #{userId}
  AND check_date BETWEEN #{start} AND #{end}

SELECT id, user_id, check_date, created_at
FROM check_in
WHERE user_id = #{userId}
  AND check_date BETWEEN #{start} AND #{end}
ORDER BY check_date ASC

SELECT user_id AS userId, COUNT(*) AS days FROM check_in WHERE user_id IN
#{uid}
GROUP BY user_id
